---@alias gcp.unstable.container_v1beta1.StatusConditionCodeEnum "UNKNOWN"|"GCE_STOCKOUT"|"GKE_SERVICE_ACCOUNT_DELETED"|"GCE_QUOTA_EXCEEDED"|"SET_BY_OPERATOR"|"CLOUD_KMS_KEY_ERROR"|"CA_EXPIRING"|"NODE_SERVICE_ACCOUNT_MISSING_PERMISSIONS"|"CLOUD_KMS_KEY_DESTROYED"

